package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;
public class RouteInspectInstrumentation extends Instrumentation {
 String tag="normal";Activity activity;android.content.SharedPreferences prefs;boolean startLive;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null)tag=b.getString("shotTag","normal");start();}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String label,boolean prefix){if(n==null||!n.refresh())return null;String t=n.getText()==null?"":n.getText().toString();if(prefix?t.startsWith(label):t.equals(label))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo x=find(n.getChild(i),label,prefix);if(x!=null)return x;}return null;}
 AccessibilityNodeInfo await(String t,boolean prefix)throws Exception{long end=SystemClock.uptimeMillis()+45000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo n=find(getUiAutomation().getRootInActiveWindow(),t,prefix);if(n!=null)return n;SystemClock.sleep(80);}throw new IllegalStateException("Missing "+t);}
 void click(String label,boolean prefix)throws Exception{AccessibilityNodeInfo n=await(label,prefix);while(!n.isClickable())n=n.getParent();if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new IllegalStateException("click "+label);SystemClock.sleep(250);}
 void shot()throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"nexttv-1.3.37-"+tag+"-route-full-address.png");values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"image/png");values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 @Override public void onStart(){int code=Activity.RESULT_OK;String result="";try{
 prefs=getTargetContext().getSharedPreferences("nexttv",0);startLive=prefs.getBoolean("start_live",false);prefs.edit().putBoolean("start_live",false).commit();
 activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));click("CCTV1综合",false);long deadline=SystemClock.uptimeMillis()+45000;boolean frame=false;while(SystemClock.uptimeMillis()<deadline){java.io.StringWriter log=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(log),null));java.util.regex.Matcher m=java.util.regex.Pattern.compile("firstFrameMs=(\\d+)").matcher(log.toString());if(m.find()&&Long.parseLong(m.group(1))>0){frame=true;break;}SystemClock.sleep(100);}if(!frame)throw new IllegalStateException("No actual video frame");sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);click("线路 ",true);await("线路选择",false);AccessibilityNodeInfo row=await("线路 1",true);while(row!=null&&!row.isLongClickable())row=row.getParent();if(row==null)throw new IllegalStateException("No long-clickable route row");if(!row.performAction(AccessibilityNodeInfo.ACTION_LONG_CLICK))throw new IllegalStateException("No long-press inspect action");await("完整地址",false);await("http",true);await("复制地址",false);shot();sendKeyDownUpSync(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(find(getUiAutomation().getRootInActiveWindow(),"线路选择",false)!=null||find(getUiAutomation().getRootInActiveWindow(),"复制地址",false)!=null)throw new IllegalStateException("Back did not close all player overlays");result="PASS route row exposes full real address through shared long-press and Back closes all overlays; no network probing\n";
 }catch(Throwable t){code=Activity.RESULT_CANCELED;result=android.util.Log.getStackTraceString(t);}finally{if(activity!=null)runOnMainSync(()->activity.finish());if(prefs!=null)prefs.edit().putBoolean("start_live",startLive).commit();}Bundle b=new Bundle();b.putString("stream",result);finish(code,b);}
}
